import React,{useState} from 'react';
export default function Journey({state='ready'}){const [step,setStep]=useState(0);if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
const labels=['Discover','Evaluate','Activate','Grow'];const details=['A useful first impression','Make the choice clear','Help the first action succeed','Build a durable habit'];return <div className="shell"><span className="eyebrow">Experience strategy</span><h1>Connect the moments that matter.</h1><p>Navigate a reference journey without losing the wider context.</p><nav className="steps" aria-label="Journey steps">{labels.map((name,i)=><button key={name} id={'step-'+i} className={i===step?'btn':'btn ghost'} onClick={()=>setStep(i)} aria-current={i===step?'step':undefined}>{i+1}. {name}</button>)}</nav><section className="panel spacer"><span className="eyebrow">Current focus</span><h2 id="result">{details[step]}</h2><p>Identify the question, the evidence and the next safe action for this moment.</p><div className="grid"><div><h3>User question</h3><p>What should I do next?</p></div><div><h3>Product responsibility</h3><p>Reduce uncertainty without hiding tradeoffs.</p></div></div></section></div>;}
